import React from "react";
import { useNavigate } from "react-router-dom";

export default function Home() {
  const nav = useNavigate();

  return (
    <div style={{ padding: 30, fontFamily: "sans-serif" }}>
      <h1>Traffic Challan System</h1>
      <p>Welcome to the system. Please choose an option:</p>

      <div style={{ display: "flex", flexDirection: "column", gap: "15px", width: "200px" }}>
        <button onClick={() => nav("/admin/login")}>Admin Login</button>
        <button onClick={() => nav("/user/login")}>User Login</button>
      </div>
    </div>
  );
}
